<script setup lang="ts">
import { ref, onMounted, computed } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useSession } from '../stores/session'
import { api, dateText, statusText } from '../api'
import { useCourseScope } from '../useCourseScope'
import { courseContent } from '../courseContent'
import Icon from '../components/Icon.vue'
import EmptyState from '../components/EmptyState.vue'
import GradeResult from '../components/GradeResult.vue'
import CodeRunner from '../components/CodeRunner.vue'
const scope=useCourseScope(), session=useSession(), route=useRoute(), rows=ref<any[]>([]), selected=ref<any>(null), code=ref(''), loading=ref(true), busy=ref(false), result=ref<any>(null), history=ref<any[]>([]), dialog=ref(false), saving=ref(false), editing=ref<number|null>(null), loadError=ref(false)
const content=computed(()=>courseContent[scope.courseId]||courseContent[1])
const form=ref<any>({}), lines=computed(()=>Math.max(8,code.value.split('\n').length))
const ownHistory=computed(()=>history.value.filter(s=>s.assignment_id===selected.value?.id))
const rubricTotal=computed(()=>form.value.rubric?.reduce((a:number,r:any)=>a+Number(r.max_score),0)||0)
const working=(s:any)=>['pending','grading'].includes(s?.status)
async function refreshRecords(){
  const [assignments,submissions]=await Promise.all([api.get(`/courses/${scope.courseId}/assignments`),api.get(`/courses/${scope.courseId}/submissions`)])
  if(!scope.active())return
  rows.value=assignments;history.value=submissions
  if(selected.value){const latest=assignments.find((a:any)=>a.id===selected.value.id);if(latest)selected.value=latest}
  if(result.value){const updated=submissions.find((r:any)=>r.id===result.value.id);if(updated)result.value=updated}
  if(submissions.some(working))scope.schedule(poll)
}
async function poll(){try{await refreshRecords();loadError.value=false}catch{if(scope.active())loadError.value=true}}
async function load(){loading.value=true;scope.stop();loadError.value=false;try{await refreshRecords();if(!scope.active())return;if(!selected.value){const id=Number(route.query.assignment)||rows.value[0]?.id;const found=rows.value.find(r=>r.id===id);if(found)choose(found)}}catch{if(scope.active())loadError.value=true}finally{if(scope.active())loading.value=false}}
onMounted(load)
function choose(a:any){if(busy.value)return;selected.value=a;code.value=a.starter_code||'';result.value=a.latest_submission}
async function submit(){if(!code.value.trim()||busy.value)return;busy.value=true;try{const data=await api.post(`/assignments/${selected.value.id}/submissions`,{code:code.value,request_id:crypto.randomUUID()});if(!scope.active())return;result.value=data;await refreshRecords();ElMessage.success(working(data)?'提交已保存，正在排队评阅':'提交与反馈已保存')}finally{if(scope.active())busy.value=false}}
async function retry(){busy.value=true;try{const data=await api.post(`/submissions/${result.value.id}/retry`);if(!scope.active())return;result.value=data;await refreshRecords()}finally{if(scope.active())busy.value=false}}
function openForm(a?:any){editing.value=a?.id||null;form.value=a?JSON.parse(JSON.stringify(a)):{title:'',description:'',topic:content.value.topics,max_score:100,status:'draft',deadline:'',starter_code:content.value.starter,rubric:[{name:'逻辑正确性',max_score:60},{name:'语法与规范',max_score:20},{name:'边界与表达',max_score:20}]};if(form.value.deadline){const raw=form.value.deadline;const zoned=/(?:Z|[+-]\d{2}:?\d{2})$/i.test(raw)?raw:raw+'+08:00';const date=new Date(zoned);form.value.deadline=new Date(date.getTime()+8*3600000).toISOString().slice(0,16)}dialog.value=true}
async function save(){saving.value=true;try{const body={...form.value,deadline:form.value.deadline?form.value.deadline+'+08:00':null};editing.value?await api.put(`/assignments/${editing.value}`,body):await api.post(`/courses/${scope.courseId}/assignments`,body);if(!scope.active())return;dialog.value=false;await load();ElMessage.success('作业已保存')}finally{if(scope.active())saving.value=false}}
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">PRACTICE MAKES UNDERSTANDING</span><h1>{{ session.isStudent?'在练习中，把知识连起来':'让练习，成为理解的起点' }}</h1><p>{{ session.isStudent?'带着思考提交，在反馈中找到下一步。':'发布课程作业，明确评分标准，为学生提供可操作的反馈。' }}</p></div><button v-if="!session.isStudent" class="btn btn-primary" @click="openForm()"><Icon name="plus" :size="17" />新建作业</button></div>
  <div v-if="loadError" class="error-box">作业记录刷新失败。<button class="text-link" @click="load">重新加载</button></div><button class="text-link task-refresh" @click="load"><Icon name="refresh" :size="14" />刷新作业与提交状态</button><div v-loading="loading" class="assignment-layout"><aside class="assignment-list"><div class="list-heading"><h3>课程作业</h3><span class="count-badge">{{ rows.length }}</span></div><button v-for="a in rows" :key="a.id" :disabled="busy" :data-testid="'assignment-'+a.id" :class="['assignment-card',{selected:selected?.id===a.id}]" @click="choose(a)"><div><span class="tag" :class="a.status==='draft'?'gray':a.latest_submission?'green':'blue'">{{ a.status==='draft'?'草稿':a.latest_submission?'已提交':'进行中' }}</span><small>{{ a.max_score }} 分</small></div><h3>{{ a.title }}</h3><p>{{ a.topic }}</p><div class="assignment-card-bottom"><span><Icon name="clock" :size="13" />{{ dateText(a.deadline) }} 截止</span><Icon name="chevron" :size="16" /></div></button><EmptyState v-if="!loading&&!rows.length" title="还没有作业" description="教师发布作业后会显示在这里。" /></aside>
    <section v-if="selected" class="assignment-detail panel"><div class="section-heading"><div><span class="eyebrow">ASSIGNMENT {{ String(selected.id).padStart(2,'0') }}</span><h2>{{ selected.title }}</h2></div><button v-if="!session.isStudent" class="btn btn-outline btn-sm" @click="openForm(selected)"><Icon name="notebook" :size="15" />编辑作业</button><span v-else class="tag blue">{{ selected.topic }}</span></div><div class="assignment-meta"><span><Icon name="clock" :size="15" />截止 {{ dateText(selected.deadline,true) }}</span><span><Icon name="target" :size="15" />满分 {{ selected.max_score }} 分</span></div><div class="assignment-description"><h4>任务要求</h4><p>{{ selected.description }}</p></div><div class="rubric-strip"><div v-for="r in selected.rubric" :key="r.name"><span>{{ r.name }}</span><b>{{ r.max_score }}<small>分</small></b></div></div>
      <template v-if="session.isStudent"><div class="section-heading editor-heading"><h4><Icon name="code" :size="18" />我的 {{ content.label }} 代码</h4><span class="small muted">{{ content.label }} · 代码评阅与执行分开记录</span></div><div class="code-editor"><div class="code-gutter"><span v-for="n in lines" :key="n">{{ n }}</span></div><textarea v-model="code" :aria-label="content.label+' 代码'" data-testid="code-input" spellcheck="false" :rows="lines" maxlength="30000"></textarea><span class="code-language">{{ content.label }}</span></div><div class="editor-actions"><span class="muted small"><Icon name="shield" :size="14" />评分是辅助建议，支持教师复核</span><button class="btn btn-primary" data-testid="submit-code" :disabled="busy||!code.trim()" @click="submit"><Icon :name="busy?'refresh':'send'" :size="16" />{{ busy?'正在处理…':'提交并获取反馈' }}</button></div><CodeRunner :code="code" :language="content.language" /><div v-if="ownHistory.length" class="history-picker"><label>提交记录</label><select :value="result?.id" @change="result=ownHistory.find(s=>s.id===Number(($event.target as HTMLSelectElement).value))"><option v-for="s in ownHistory" :key="s.id" :value="s.id">{{ dateText(s.created_at,true) }} · {{ statusText[s.status] }}{{ s.is_seed?' · 样例':'' }}</option></select></div><div v-if="working(result)" class="task-progress"><Icon name="clock" :size="20" /><div><b>{{ statusText[result.status] }}</b><p>提交已保存，反馈将自动刷新。也可稍后从提交记录继续查看。</p></div></div><div v-if="result?.status==='failed'" class="error-box"><Icon name="alert" :size="20" /><div><b>提交已保存，批改暂未完成</b><p>{{ result.error }}</p><button class="btn btn-outline btn-sm" :disabled="busy" @click="retry">重试批改</button></div></div><GradeResult v-if="result&&!working(result)" :key="result.id+'-'+result.attempts" :submission="result" /></template><div v-else class="teacher-assignment-note"><Icon name="review" :size="26" /><h3>评分标准已准备就绪</h3><p>学生提交后，可在批改复核中确认建议分与反馈。</p><RouterLink to="/reviews" class="btn btn-primary">查看学生提交<Icon name="arrow" :size="16" /></RouterLink></div>
    </section><section v-else class="panel assignment-detail"><EmptyState title="从左侧选择一份作业" /></section></div>
  <el-dialog v-model="dialog" :title="editing?'编辑作业':'创建课程作业'" width="660px"><form class="stack-form" @submit.prevent="save"><label>作业标题<input v-model="form.title" required maxlength="100" /></label><label>任务要求<textarea v-model="form.description" required rows="4" maxlength="10000"></textarea></label><div class="form-grid"><label>知识点<input v-model="form.topic" required maxlength="100" /></label><label>截止时间（北京时间）<input v-model="form.deadline" type="datetime-local" /></label></div><div class="section-heading"><h4>评分标准</h4><span class="small" :class="rubricTotal!==Number(form.max_score)?'text-orange':'text-blue'">合计 {{ rubricTotal }} / {{ form.max_score }} 分</span></div><div v-for="(r,i) in form.rubric" :key="i" class="rubric-input"><input v-model="r.name" placeholder="评分维度" required maxlength="60" /><input v-model.number="r.max_score" type="number" min="1" max="100" required /><button v-if="form.rubric.length>1" type="button" class="icon-btn" aria-label="删除维度" @click="form.rubric.splice(i,1)"><Icon name="x" :size="16" /></button></div><button v-if="form.rubric?.length<10" type="button" class="text-link" @click="form.rubric.push({name:'',max_score:10})"><Icon name="plus" :size="15" />增加维度</button><label>初始代码<textarea v-model="form.starter_code" rows="3" class="mono" maxlength="20000"></textarea></label><label>发布状态<select v-model="form.status"><option value="draft">保存为草稿</option><option value="published">立即发布</option></select></label><p class="small muted">评分依据当前题意与评分标准，AI 建议支持教师复核；历史演示反馈保留原有标记。</p><div class="dialog-actions"><button type="button" class="btn btn-outline" @click="dialog=false">取消</button><button class="btn btn-primary" :disabled="saving||rubricTotal!==Number(form.max_score)">{{ saving?'保存中…':'保存作业' }}</button></div></form></el-dialog>
</template>
